package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Takes statements of people. A statement records the person's due-total and binds each of their counting
 * claims to the due it shows then; their other claims are left unbound, so their dues are live again.
 */
@Service
public class StatementService {

    private final StatementRepository statements;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateService rates;
    private final SheetService sheets;
    private final Audit audit;
    private final RollupService rollup;

    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
            RateService rates, SheetService sheets, Audit audit, RollupService rollup) {
        this.statements = statements;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** Each person's statement summary on the sheet, by person id; a person with none is missing. */
    public Map<Long, StatementSummary> summaries(String sheetId) {
        Map<Long, StatementSummary> by = new HashMap<>();
        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
            by.put(s.getPersonId(), by.getOrDefault(s.getPersonId(), StatementSummary.NONE).then(s));
        }
        return by;
    }

    public StatementSummary summary(String sheetId, Long personId) {
        StatementSummary summary = StatementSummary.NONE;
        for (Statement s : statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId)) {
            summary = summary.then(s);
        }
        return summary;
    }

    @Transactional
    public Person take(String sheetId, String user, Long personId) {
        Person person = people.findForUpdate(personId, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, personId));
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Sheet sheet = sheets.get(sheetId);
        LocalDate today = sheet.getToday();
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        // As on the screen: n/a when the grade in force today has no rate today, unless a counting claim has a fixed due
        // or a due on or before today.
        boolean anyDue = rates.rateOn(sheetId, person.gradeOn(today), today).isPresent();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        int counted = 0;
        for (Claim claim : theirs) {
            if (!person.counts(claim, today)) {
                claim.setStated(false, null);
                continue;
            }
            counted++;
            if (claim.getSettledDue() != null || claim.getBoundDue() != null) {
                anyDue = true;
            }
            // The statement binds the rate figure under the claim's due; its late charge keeps following the sheet's
            // today, and the floor is applied last.
            BigDecimal figure = figureOf(sheetId, person, claim).orElse(null);
            BigDecimal due = claim.getSettledDue() != null || claim.isCorrection() ? figure
                    : sheet.floored(sheet.withLateCharge(figure, claim.getStatus().isOpen(), claim.getDueBy(),
                            claim.getDate()), claim.getDate());
            if (due != null) {
                total = total.add(due);
                // A due under a grade the person had on an earlier date counts too.
                if (!claim.getDate().isAfter(today)) {
                    anyDue = true;
                }
            }
            claim.setStated(true, figure);
        }
        claims.saveAllAndFlush(theirs);
        String dueTotal = anyDue ? sheet.capped(total).toPlainString() : "n/a";
        statements.saveAndFlush(new Statement(sheetId, personId, today, dueTotal, counted));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + dueTotal + " claims=" + counted);
        rollup.recordChanges(sheetId, user, before);
        return person;
    }

    /**
     * The figure under the claim's due: the due fixed when it was settled, else the one its last statement bound it
     * to, else its amount times its grade's rate on its date (no floor); empty when it has none (n/a).
     */
    private Optional<BigDecimal> figureOf(String sheetId, Person person, Claim claim) {
        if (claim.getSettledDue() != null) {
            return Optional.of(claim.getSettledDue());
        }
        if (claim.isBound()) {
            return Optional.ofNullable(claim.getStatedDue());
        }
        return rates.rateOn(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
                .map(Rate::getPct)
                .map(pct -> sheets.get(sheetId).rateStep(claim.getAmount(), pct, claim.getRoundingDate()));
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A statement taken of a person: their due-total and how many of their claims counted, on the sheet's today. */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    /** Two decimals, or n/a when the person's due-total had none. */
    @Column(name = "due_total", nullable = false)
    private String dueTotal;

    @Column(name = "claims", nullable = false)
    private int claims;

    protected Statement() {
    }

    public Statement(String sheetId, Long personId, LocalDate takenOn, String dueTotal, int claims) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.takenOn = takenOn;
        this.dueTotal = dueTotal;
        this.claims = claims;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public LocalDate getTakenOn() {
        return takenOn;
    }

    public String getDueTotal() {
        return dueTotal;
    }

    public int getClaims() {
        return claims;
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.StatementService;
import net.officefloor.hq.app.statement.StatementSummary;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The people on a sheet. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/people")
@Validated
public class PersonController {

    /** One of a person's holds, from its from-date to its to-date (null: it does not end). */
    public record HoldView(LocalDate from, LocalDate to) {
    }

    /** One of a person's grades, from its from-date (null: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {
    }

    /**
     * A person as shown, with their grade in force on the sheet's today and every grade with its from-date, with how many statements they have had and the due-total and date of the last one. */
    public record PersonView(Long id, String name, String grade, Integer terms, long version, int statementCount,
            String statedTotal, LocalDate statementDate, boolean retired, LocalDate retiredFrom, boolean held,
            List<Long> patronIds, List<GradeView> grades, List<HoldView> holds, boolean watched) {

        static PersonView of(Person person, LocalDate today, StatementSummary statements, List<Long> patronIds,
                boolean watched) {
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today), person.getTerms(),
                    person.getVersion(),
                    statements.count(), statements.lastDueTotal(), statements.lastDate(),
                    person.isRetired(), person.getRetiredFrom(), person.isHeld(), patronIds,
                    person.getGrades().stream().map(g -> new GradeView(g.getGrade(), g.getFromDate())).toList(),
                    person.getHolds().stream().map(h -> new HoldView(h.getFromDate(), h.getToDate())).toList(),
                    watched);
        }
    }

    public record PersonRequest(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate gradeFrom,
            @Pattern(regexp = "\\s*(\\d{1,5})?\\s*") String terms,
            Long version) {

        /** The person's own terms in whole days; null when blank. */
        Integer termsValue() {
            return terms == null || terms.isBlank() ? null : Integer.valueOf(terms.trim());
        }
    }

    /** The date to retire from; null for the sheet's today. */
    public record RetireRequest(LocalDate from) {
    }

    /** The dates a hold runs from (null: the sheet's today) and to (null: it does not end). */
    public record HoldRequest(LocalDate from, LocalDate to) {
    }

    /** The person to name as a patron. */
    public record PatronRequest(@NotNull Long patronId) {
    }

    /** Whether the signed-in user is to watch the person. */
    public record WatchRequest(@NotNull Boolean on) {
    }

    private final PersonService service;
    private final StatementService statements;
    private final SheetService sheets;
    private final WatchService watches;

    public PersonController(PersonService service, StatementService statements, SheetService sheets,
            WatchService watches) {
        this.service = service;
        this.watches = watches;
        this.statements = statements;
        this.sheets = sheets;
    }

    /** The sheet's people in the order they were added. */
    @GetMapping
    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        Map<Long, StatementSummary> summaries = statements.summaries(sheetId.trim());
        Map<Long, List<Long>> patronIds = service.patronIds(sheetId.trim());
        Set<Long> watched = watches.watchedBy(sheetId.trim(), user.trim());
        List<Person> people = service.list(sheetId.trim());
        LocalDate today = people.isEmpty() ? null : sheets.today(sheetId.trim());
        return people.stream()
                .map(p -> PersonView.of(p, today, summaries.getOrDefault(p.getId(), StatementSummary.NONE),
